      "summary": "小学一至六年级。把校园闲置荒地交给学生投票改成菜园，再按真实问题往下长铺路、灌溉、造屋、稻麦和面包窑；低段两节美术连堂，四到六年级美劳三连上。2021年春，校园约一亩废弃花园由学生投票决定用途，选定种菜。开荒先铺路：美术课比较中外纹样、学马赛克镶嵌，劳动课学水泥配比，学生按图纸把彩色石子按进水泥，一席记录干了三节课铺出约 67 米小路，教育报称此为「道路SPA课程」。菜园之后按现场问题接着生发：周末灌溉立项铺管；工具杂乱则六年级「造屋计划」搭工具房，三年级接续收纳与标语；盟校送来兔子后研究习性并做防护；北方试种水稻，第一年失败后做生命教育，第二年改良并延伸「稻麦课程」。没有烹饪教室时，学生在新楼东侧三角地自建面包窑：就地筛土、掺麦秆、用废啤酒瓶做保温层。窑建成后开比萨、面包课，从和面做到定价售卖；窑温不足再开发迷你柴窑烧陶。一席写面包窑已迭代到 3.0 版。课时组织：实习期起把两节美术连上（含课间约 90 分钟）；四年级起使用劳动工具；四到六年级把两节美术加一节劳动改成三连上，少反复收工具换场地。一席写一到六年级有校本课程设计：低段侧重拓宽材料与形式，中高段转向解决真实问题的项目。校园与社区延伸：楼层小微展厅常态展示学生作品；「三分地家庭菜园」划分 80 余个家庭责任田；校门口家庭策展橱窗（一席称家庭美育橱窗，教育报称「5.76艺术盒子」）；联动街道做马路诗歌节。教育报还写到合计花园、鱼菜共生、蚯蚓塔、鸡兔养殖等后续项目。授课教师原文未写。当堂书面作业原文未写。",
