        "参照结构列出自己文章的要点，要有个人看法、不健康的习惯和反思、改进办法。",
        "第二次回到范文，把每个习惯下面的具体做法补进结构图，再判定自己哪些习惯健康、哪些不健康、准备怎么改，补进自己的提纲。",
        "第三次回到范文，找出介绍习惯时用的短语、however、although、but、表示多久一次的词，以及 need to 和比较级，按提纲写成初稿。",
        "用是否表自查：有没有反思健康程度，第一段有没有总体评价，有没有分段写不同方面，细节够不够，最后一段有没有写改进办法，句型和用词是否合适，拼写、语法和标点是否正确。答“否”的写下怎么改，形成二稿。",
