        "地震先做避险再疏散。避险警报长鸣60秒。学生就近蹲或躺在课桌、实验台或床铺旁边，或靠承重墙，护住头、蜷起身体，不靠近窗口，避开灯扇。实验室同时关闭火源、电源、气源。避险结束后再发疏散警报：长鸣60秒、停30秒，反复两遍。中学生从疏散信号到完成，目标在2分钟以内。",
        "火灾不先避险，直接疏散，口令改为“现在发生火灾”。有烟时用衣服或毛巾捂住口鼻，放低身体。不拥挤，不回头跑，不弯腰捡东西，不坐普通电梯。前面有人摔倒就停下并呼救。七层以上不跳楼；十楼以下走楼梯；十二楼及以上用湿毛巾捂住口鼻，到天台或阳台等候救援。",
