      "summary": "五年级的家长和孩子先分开坐。每人在纸上写下最爱的食物、偶像、鞋码、优点和缺点，不写名字；小组把纸打乱，换到另一组，让大家从纸上找出自己的家人，再当面核对。接着孩子蒙上眼，在摆了椅子的房间里走，家长只能用一只手搭在自己孩子肩上，全程不说话。最后每人把家里的人画成动物，和家人交换，猜每只动物是谁。",
