        "两组把纸汇总打乱，换到对方的圆圈里。每人从面前的纸里找出自己的家人，找家人核对是否找对，再回到大组说自己看出了什么、没看出什么。",
        "把椅子散开当路障。孩子蒙眼走动。家长只能用一只手搭在自己孩子肩上，走在身后，何时加入自己决定。从开始到结束都不许说话，结束后才摘眼罩。",
        "家长和孩子先谈这一路各自怎么想、是否默契。教师再问几位家长凭什么决定加入，孩子对这只手是什么感觉。",
        "三个家庭一组。每人把自己和家人想象成动物，画出他们在一起的场面。孩子和父母各画各的。画完互换，在对方的画上标出自己猜的「这只动物是谁」。",
        "每人在小组里介绍自己的画：每只动物有什么特点、他们在一起做什么。最后以家庭为单位把画贴出来，家长和孩子再分开，各用约5分钟写下现在想对家人说的话，回家后交给家人。"
