      "summary": "小学四年级心理课。先看一只装着糖的罐子，猜课后糖会变多、变少，还是不变，答案先不说。每人得到一颗糖，在学习单上写准备送给谁、要说什么。送的时候看着对方的眼睛，说出感谢、夸赞、邀请、鼓励或祝福。想不出来的人看黑板上的甜蜜任务卡。没有收到糖的，教师再送一颗，并说一句鼓励或夸奖。四人一组，在甜蜜记录卡上写送出和收到时的感受，并说如果对方只是随口道谢、或正在跟别人说话，下一步可以换一个人或换一种方式。再在贴纸上写一条今后愿意做的友好行动，按小组贴到友谊糖果屋海报上。最后把糖投回罐子：只送出投1颗，只收到投1颗，又送又收投2颗。文章里这一次的结果是罐子里的糖变多了。",
