      "summary": "小学五、六年级心理课。先听一段不同语气的话，觉得非常不舒服就用力揉手里的白纸，没什么感觉就让纸保持平整。再看四幅图：起侮辱性外号、背后说坏话、造谣、当众嘲笑，说这样的事身边有没有。接着比较两个外号：一个孩子被叫「狗熊」，自己觉得威武；一个孩子被叫「熊猫」，觉得是在笑自己的身材。小组讨论怎样才算言语欺凌。教师归纳的标准是看听的人难不难受，不看说的人有没有恶意。然后写转学生查理在原来学校可能听过的伤人的话，投进纸箱。抽出几张，对着画像念，每念一句，教师把画像揉一下。等画像变成纸团，每人说一句鼓励的话，教师把纸慢慢展开。小组填写防暴盾牌。文章里当场说出来的做法是告诉教师或家长，以及大声说「我不喜欢这样」，请对方停止。",
