      "summary": "初中七年级心理课。先看一件印着夸张卡通头像的T恤，投票走进满教室的人里会有多少人注意到，选项是一成、两成、五成、八成、全部。教师把人数写在黑板上，并告诉学生：一项实验里，穿尴尬T恤的人预测至少一半人会看，实际注意到的不到两成。然后一位男生站到门口，戴上面具，演小北。发型这一幕，全班举课前发的A牌或B牌。A是快步回到座位，躲开目光；B是直接问同学是不是在议论新发型。两种都演。球场这一幕，决赛最后一次传球偏了，队友当众指责。A是立刻反驳，B是沉默离开。全班分成两组，各派一人到台前记录，限时四分钟轮流说。学生发现两条路都还在想「大家都在看我」。四人一组讨论第三条路，归纳成行动优先和现实检验。最后问：这个月数学课上答错过的举手；再问其他人还记不记得那个人具体说了什么。演小北的同学摘下面具。",
