      "summary": "初一上学期期末前的一节心理课。音乐响起，小组里传递一只鸭梨玩偶；音乐停，玩偶在谁手里，谁就说一件近期的烦恼。然后给自己的学习压力举手臂：平举是5分，举得越高越紧张，最高10分，放得越低越从容，最低0分，并说为什么。七个压力来源逐条出现，符合自己的，就用右手往左手小臂上加一本书，七本书是语数外政史地生。教师倒数10秒，再慢慢放下。接着两到三人一组，一人演小乐，一人演压力君，可以有旁白，按给出的句式对话三分钟。学案纸上写下自己用来缓解学习压力的方式。课后从清单里选三种，在期末复习里去做。",
