      "summary": "初一心理课。先听一只山羊看自己影子的故事：影子长就觉得自己够得着果子，影子短又跑回去吃白菜，忙了一天什么也没吃到。然后五到六个小组围坐。每人十分钟，在白纸上画自画像，可以画自己，也可以画能代表自己的动物或植物，再写三个词。代表向全班讲自己的画。接着交换画，给组里每一个其他人写优点，尽量多写，尽量不重复。拿回自己的画，看有哪些优点是自己没写过的。再在旁边画理想中的自己，写下现在和理想差在哪里、还有什么不足、准备怎么改。从这些不足里选一个或两个，班长登记。每人做一张打卡表，之后每一天做到了就在当天打勾，一个月后交给教师。教师按打卡打分，选出五位得分最高的，发奖状和礼物。课中会看一段名为《你远比想象的美丽》的视频，文章没有写出画面。",
