      "summary": "小学五年级。学生先用摇杆控制飞船在画面上写出「中国」，确认要能左移、右移、上移、下移。摇杆放在中间先记一次A1，再拨到最右和最左，记下最大值1023和最小值0。然后亲自拨到A1刚好是600的位置，这个600就是右拨时用来比较的数；左拨时用来比较的数是400。用「如果……那么……」画成分支流程图，再按图在Mind+里搭脚本验证。加上从上方落下的陨石和从右侧移动的能量条之后，有人把移动数值加大，飞船又变得太快、抓不准能量条，于是改成拨到最边上才加速：A1小于100或大于900，A2小于100。",
      "practices": [
        "用摇杆控制飞船在画面上写出「中国」，再说出需要左移、右移、上移、下移；再画一条斜线，确认斜线也是这四个方向合起来的。",
        "在课件上拖动圆点，看摇杆怎样改变电位器。在Mind+里记下摇杆A1、A2的数值和飞船移动方向。",
        "摇杆放在中间，记录A1。拨到最右边和最左边，记录A1的最大值1023和最小值0。中间读数不同摇杆会有差别，不写成一个固定数。",
        "拨到靠近最右边，先猜A1大约是多少；再问A1是800、是600时摇杆该在哪里，并亲自拨到A1为600的位置。右拨的判断就用这个600，用来避开摇杆初始位置的误差。",
        "用这句话填空：检测摇杆右拨，通过摇杆X值与空白处的比较进行判断，如果空白，那么就让飞船执行空白命令。再把「如果……那么……」画成分支流程图。",
        "按流程图在Mind+里找到控件，搭脚本，验证摇杆右拨。左拨再找比较值400，同样写自然语言、画流程图、搭脚本验证。上拨、下拨由小组互相借鉴着做。",
        "加上陨石和能量条：陨石从上方随机落下，能量条从右侧随机移动，摇杆控制飞船去接能量条，碰到陨石就失去能量。",
        "有人提议加大飞船移动的数值，一试发现移动过快，难以接住能量条。观察自己躲陨石时会把摇杆拨到最左、最右、最下，此时A1小于100或大于900，A2小于100。按这些条件改算法，再搭脚本运行。"
      ],
