      "summary": "小学放学前的一段班会。教师说，今天中午有同学没把饭吃完，把饭盒放回饭箱，午餐管理老师因此批评了自己。学生要帮着把人找出来，教师说不用，并和学生一起背《千人糕》里的一段：一块平平常常的糕，经过很多很多人的劳动，才能摆在我们面前。然后每人一张便利贴。不是自己做的，写「我没有」三个字；是自己做的，写「我错了」3个字。写好折起来，放进讲台上的盒子。放学后教师打开，一连二十几个写的是「我没有」，最后有一张蓝色的写着「我错了」。晚上教师写一封信，第二天体育课放进那个学生的书包，约定这件事不告诉别人。第三天，备课笔记里夹着一封回信。",
