        "有学生说要帮老师把这个人找出来。教师说不用。教师接着说：有时候自己早上吃得比较饱，或者遇到不喜欢的菜也不想吃；但一想，这些饭菜是营养师精心搭配的，食堂的人很早就要到学校工作，一盒饭菜背后是许多人的劳动，所以每次都光盘了。",
        "教师背《千人糕》里的一段，学生一起背：一块平平常常的糕，经过很多很多人的劳动，才能摆在我们面前。所以我们应当尊重每个人的劳动成果。",
        "教师说：如果身体不舒服，或者没有胃口，可以提前和午餐管理老师沟通，少盛一些，以免浪费。然后每人发一张便利贴。不是自己做的，写「我没有」三个字；是自己做的，写「我错了」3个字。写好后折起来，放到讲台上的盒子里。",
        "学生放学后，教师打开盒子。一连二十几个便利贴写的都是「我没有」。最后有一张蓝色的，写着「我错了」。",
        "当天晚上，教师写了一封信。信里写的是：欣赏知错就改的勇气；勇敢是最稀缺的品德，现在有了就不能弄丢；以后如果实在吃不完，就跟老师沟通；这件事当作两个人的小秘密，不告诉别人。第二天学生上体育课时，教师把信放进那个学生的书包。",
