      "summary": "小学一节听说课，学生看打乱的三幅图，猜智者送镜子时摔倒、镜子碎成七块，听三遍后按图把这段讲回来，再假设自己是智者说出怎么办；听完后半段，同桌分角色演智者把碎片拼给国王，最后小组用七巧板拼出几块图形，连成一个故事讲出来。",
