        "拿出《能量工程师工作手册》和黑笔。回想最近一周一件特别开心、有成就感或感到温暖的小事，简单写或画下来。再写两问：当时心里什么感觉，身体有没有特别的反应。记下来的有：帮奶奶浇花被夸懂事，心里甜甜的，身体轻松；跑步比同桌快、得了小组第一，心里骄傲，脸有点发烫。然后闭上眼，再回忆一次那种感觉。",
        "课件响起警报。读小雨的故障报告，日期是3月28日星期五。早上闹钟没响，跑到教室差点迟到，满头大汗，同桌递纸巾，并说数学题全部做错、被教师批评；课间十分钟被叫去办公室学习，感觉自己很笨。体育课跑步摔倒，感觉所有同学在笑自己像乌龟，马上起来回到队伍，保洁阿姨帮忙简单洗了衣服，下午抬不起头，下课后阿姨给了一块糖。美术课作品被说画得像垃圾，感觉被所有人讨厌，生气地把作品折成了青蛙。结尾写自己一无是处。",
        "启动「能量感应器」。一分钟内用红笔圈出报告里的积极线索，可以举手说。学生圈出的有：同桌递纸巾；被教师叫去办公室学习；保洁阿姨洗了衣服并给了一块糖；美术作品折成了青蛙；摔倒后马上起来。教师归纳：他人帮助、单独辅导、自我起来，都算被忽略的线索。",
        "启动「能量扫描仪」。仍用红笔，在故障报告里划掉标签类、绝对化、否定式的故障词，约两分钟。例子是「真的很笨」。学生划出的句子有：感觉自己真的很笨；所有人都在笑我像乌龟；被所有人讨厌。再问这些是事实，还是自己生成的错误警报。学生说「笨」可能只是这个知识点没理解。教师说「笨」是标签不是事实，「一无是处」是以偏概全。",
        "能量转换器用四句：虽然（描述糟糕的事件），但这不代表（撕掉负面标签），事实上（客观证据或积极细节），我可以（做得到的行动）。教师先带全班改「我真的很笨」：虽然数学题全部做错了，但这不代表我真的很笨，事实上教师单独辅导了十分钟数学，我可以从今天开始每天多做两道例题。",
        "继续改两条：美术作品被说像垃圾；体育课摔倒，被同学说像乌龟。记下来的两则改写是：虽然作品被说成垃圾，但这不代表毫无价值，事实上想表达自己的情绪，还意外学会了折青蛙，可以多练习；虽然摔倒还被调侃像乌龟，但这不代表笨拙、做不好运动，事实上摔倒时用手撑住了、没有受伤，阿姨整理了衣服，下次运动前做热身、注意脚下。",
        "自我检修：用黑笔写一件自己的坏心情，用感应器圈出积极线索，用扫描仪划掉故障词，再用四句写出新的想法。记下来的有三则：画画没被表扬，改成画的小动物很可爱、可以多练习涂色；竞选班长失败，改成有竞选的勇气、得到了投票、下次可以竞选体育委员；和妹妹发生矛盾时觉得父母偏心，改成妈妈会做自己爱吃的红烧肉、爸爸考试前会陪着整理错题，等大家都冷静了再把自己的想法说出来。",
        "一起复述三步：能量感应器找积极线索，能量扫描仪找故障思维，能量转换器改写想法。教师给每人贴一张「心情工程师」贴纸。发放一周维保手账，栏目是：时间、天气、今日最佳好心情、意外亮点（积极事件）、能量感应、能量扫描、能量转换。约定下周五看维保日志。"
