        "一分钟，凭第一反应尽量多写理想朋友的特质，可以从外貌、性格、兴趣、能力来想。每组选出两条多数人认可的，组长写在黄纸条上，上台贴到人偶正面。教师念到正面上的词有：真诚、开朗、幽默、趣味相投、乐于助人。问生活里有没有遇到这样的朋友，分已经遇到和还没遇到举手。大多数人已经遇到。学生说到的有：有的朋友乐于助人、性格好，相处轻松，好像没有矛盾；有的只符合富有和颜值高，小学时因为两人都强势闹过矛盾；有的真诚，但有时太爱炫耀、说话太直，会不舒服。",
        "小组看自己贴在人偶上的两条。喜欢的那一面写在黄纸条上，已经贴在正面。不舒服的另一面写在蓝纸条上，贴到人偶背面。学生写出的另一面有：聪明的另一面是有时自以为是，觉得别人反应慢、会不耐烦；乐于助人的另一面是管得太多、越界；趣味相投的另一面是只在乎共同爱好，对朋友的其他方面不够关心；颜值高的另一面是很多人想和他玩，跟自己玩的时间变少。",
        "看着同时有正反面的人偶，问还愿不愿意和他做朋友。有人举手愿意，有人犹豫。学生说到的有：愿意，因为没有完全完美的朋友，交到朋友不容易；要看另一面是什么，如果是撒谎、不诚实，可能就不想继续；有另一面反而说明他是真实的，不假装完美。教师说，正因为真诚才可能直言，正因为活泼才可能有时吵，正因为乐于助人才可能偶尔越界。",
        "每组若干张图卡和一个信封。按手里的卡片和信封里的故事续写，想故事里的人最后可能怎么化解，并总结一条相处的办法。信封一：小A热情，但做事马虎、不负责任，小组作业和值日总是敷衍，事情落在你一个人身上。信封二：小B和你都喜欢动漫，但说话不顾你的感受，随口吐槽你的缺点，还会把你的秘密告诉别人。信封三：小C活泼、爱社交，是小学同学，结交新朋友后经常临时爽约，聚会里冷落你，有一次大吵一架。",
        "学生总结的办法有：有一组说把感受说出来，并约定以后说悄悄话时先说「这只告诉你」，对方就不能再说出去，他们的一条是「沟通」。另一组补「心平气和地沟通」，觉得语气太冲会让对方不舒服。有一组说先冷静，再把意见说出来，或者先写信再面对面说；如果对方不承认，就可以不再来往，以后承认了还可以和好，但秘密要事先约定。有一组说可以去公园或海边谈，一条是互相包容、互相理解。有一组说对方经常为了别人忽略自己，也可以自己玩、不再做朋友。教师听到「不再来往」时说，这个词常常是在生气时说出来的，不如先换成「冷静期」：当下不知道怎么办，就留一点时间，再决定下一步。",
